import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/legacy/前端系列/离不开的解决问题的思路大全.md","filePath":"wiki/legacy/前端系列/离不开的解决问题的思路大全.md"}'),i={name:"wiki/legacy/前端系列/离不开的解决问题的思路大全.md"};function h(l,a,_,n,d,s){return r(),t("div",null,[...a[0]||(a[0]=[o('<p>遇到一个新的问题，我们可以用到很多解决问题的思路，下面的内容涵盖了大部分情况。</p><h4 id="_1、直观而系统的方式。" tabindex="-1">1、直观而系统的方式。 <a class="header-anchor" href="#_1、直观而系统的方式。" aria-label="Permalink to &quot;1、直观而系统的方式。&quot;">​</a></h4><p>有些问题看一眼就能想到解决办法，如果遇到这种问题，你是很幸运的！</p><h4 id="_2、在心里问自己-以前解决过类似的问题吗" tabindex="-1">2、在心里问自己，以前解决过类似的问题吗？ <a class="header-anchor" href="#_2、在心里问自己-以前解决过类似的问题吗" aria-label="Permalink to &quot;2、在心里问自己，以前解决过类似的问题吗？&quot;">​</a></h4><p>如果有，可以找到你的笔记，或者在心里会想思路，如果没有，那么继续往下看。</p><h4 id="_3、有没有简单的方法" tabindex="-1">3、有没有简单的方法 <a class="header-anchor" href="#_3、有没有简单的方法" aria-label="Permalink to &quot;3、有没有简单的方法&quot;">​</a></h4><p>无论是解决什么问题，一开始都要从你能解决的最简单的用例入手，比如在面试的时候，面试官考察你的算法题，往往先思考第一个用例的实现，这样能快速找出规律。</p><h4 id="_4、把规律公式化" tabindex="-1">4、把规律公式化 <a class="header-anchor" href="#_4、把规律公式化" aria-label="Permalink to &quot;4、把规律公式化&quot;">​</a></h4><p>很多问题都和数学息息相关，当然，这个公式化也不仅仅表示数学公式，还可以是伪代码表达式。</p><h4 id="_5、简化问题" tabindex="-1">5、简化问题 <a class="header-anchor" href="#_5、简化问题" aria-label="Permalink to &quot;5、简化问题&quot;">​</a></h4><p>当问题的前提条件很多、或者存在多维的情况下，尝试着去掉一些次要的条件、降低维度来找到问题的切入口。</p><h4 id="_6、几何图表达" tabindex="-1">6、几何图表达 <a class="header-anchor" href="#_6、几何图表达" aria-label="Permalink to &quot;6、几何图表达&quot;">​</a></h4><p>很多问题都是从需求里面提出来的，但是这些需求通常都是纯文字，如果能够转换成几何图来表示，会很有帮助，最简单的例子是刚学流程图的时候，将if else 用流程图表示出来，让人一眼就能看得明白。</p><h4 id="_7、分解问题" tabindex="-1">7、分解问题 <a class="header-anchor" href="#_7、分解问题" aria-label="Permalink to &quot;7、分解问题&quot;">​</a></h4><p>问题的条件很多的时候，除了简化，还可以分解，根据条件之间的关联分解成不同的区间。</p><h4 id="_8、神奇的倒序" tabindex="-1">8、神奇的倒序 <a class="header-anchor" href="#_8、神奇的倒序" aria-label="Permalink to &quot;8、神奇的倒序&quot;">​</a></h4><p>在很多时候，前端工程师使用for解决数组问题时，会用到倒序遍历的方法，用过的人，说明你已经比较擅长使用算法的思路解决问题了。</p><h4 id="_9、排序可以解决很多问题" tabindex="-1">9、排序可以解决很多问题 <a class="header-anchor" href="#_9、排序可以解决很多问题" aria-label="Permalink to &quot;9、排序可以解决很多问题&quot;">​</a></h4><p>对杂乱无章的元素进行排序，通常适用于快速查找某些元素、展示等功能。</p><h4 id="_10、只考虑特殊的个体答案" tabindex="-1">10、只考虑特殊的个体答案 <a class="header-anchor" href="#_10、只考虑特殊的个体答案" aria-label="Permalink to &quot;10、只考虑特殊的个体答案&quot;">​</a></h4><p>有时候问题的实际答案是一个集合，但是我们不需要将集合的所有元素都找出来，比如判断数组中是否包含‘对象元素’。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>以上解决问题的思路来自《算法问题实战策略》</p>',23)])])}const u=e(i,[["render",h]]);export{p as __pageData,u as default};
